class GameItem {
  constructor(name, weight) {
    this.name = name;
    this.weight = weight;
  }

  getInfo() {
    return `${this.name} (Weight: ${this.weight} kg)`;
  }
}

class MeleeWeapon extends GameItem {
  constructor(name, weight, damage) {
    super(name, weight);
    this.damage = damage;
  }

  attack() {
    return `Swinging the ${this.name} for ${this.damage} damage!`;
  }
}

